.sample-message .email-head { padding: 10px 14px; }
.sample-message .avatar { width: 34px; height: 34px; font-size: 15px; }
.sample-message .email .body { padding: 10px 14px; font-size: 15px; line-height: 1.5; }
.sample-message .link { padding: 0 14px 12px; }
.sample-message .email-actions { display: none; }   /* Reply / Forward aren't part of the lesson */
/* The example Phish / Legit are pictures of the buttons, not buttons */
.sample-answers .answer {
  display: flex; align-items: center; justify-content: center;
  padding: 10px; border-radius: 10px; font-weight: 600; cursor: default;
}
.sample-progress { display: flex; align-items: center; gap: 10px; }
.sample-progress-label { font-size: 13px; color: var(--muted); }
/* Example dots are a little bigger so the ✓ and ✗ fit inside */
.sample-dots .dot {
  width: 20px; height: 20px; display: inline-flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 800; line-height: 1; color: var(--navy); animation: none;
}
.sample-dots .dot.current { transform: none; }
.practice-note { margin: 0; font-size: 13px; color: var(--muted); }

